      "class": "OTHER"
    },
    "briefTitle": "Three Drugs in Advanced Gastric Cancer Neoadjuvant Chemotherapy for Stage Ⅲ Clinical Study",
    "officialTitle": "Three Drugs in Advanced Gastric Cancer Neoadjuvant Chemotherapy for Stage Ⅲ Multicenter, Open, Randomized, Controlled Clinical Study"
  },
  "statusModule": {
    "statusVerifiedDate": "2023-10",
    "overallStatus": "COMPLETED",
    "expandedAccessInfo": {
      "hasExpandedAccess": false
    },
    "startDateStruct": {
      "date": "2014-11"
    },
    "primaryCompletionDateStruct": {
      "date": "2021-12",
      "type": "ACTUAL"
    },
    "completionDateStruct": {
      "date": "2022-06",
      "type": "ACTUAL"
    },
    "studyFirstSubmitDate": "2015-07-22",
    "studyFirstSubmitQcDate": "2015-09-18",
    "studyFirstPostDateStruct": {
      "date": "2015-09-21",
      "type": "ESTIMATED"
    },
    "lastUpdateSubmitDate": "2023-10-17",
    "lastUpdatePostDateStruct": {
      "date": "2023-10-19",
      "type": "ACTUAL"
    }
  },
  "sponsorCollaboratorsModule": {
    "responsibleParty": {
      "type": "SPONSOR_INVESTIGATOR",
      "investigatorFullName": "Qun Zhao",
      "investigatorTitle": "Surgical director",
      "investigatorAffiliation": "Hebei Medical University"
    },
    "leadSponsor": {
      "name": "Qun Zhao",
      "class": "OTHER"
    },
    "collaborators": [
      {
        "name": "Jiangsu HengRui Medicine Co., Ltd.",
        "class": "INDUSTRY"
      }
    ]
  },
  "designModule": {
    "studyType": "INTERVENTIONAL",
    "phases": [
      "PHASE2"
    ],
    "designInfo": {
      "allocation": "RANDOMIZED",
      "interventionModel": "FACTORIAL",
      "primaryPurpose": "TREATMENT",
      "maskingInfo": {
        "masking": "NONE"
      }
    },
    "enrollmentInfo": {
      "count": 300,
      "type": "ACTUAL"
    }
  },
  "armsInterventionsModule": {
    "armGroups": [
      {
        "label": "A（DOX）",
        "type": "EXPERIMENTAL",
        "description": "Interventions：This arm wil receive four cycles of DOX (docetaxel 60mg/m2 on day 1,oxaliplatin 130mg/m2 on day 1 and capecitabine 1,000 mg/m2 per day on days 1 to 14, repeated every 3 weeks) as neoadjuvant therapy and four cycles of Xelox (capecitabine 1,000 mg/m2 per day on days 1 to 14 and oxaliplatin 130mg/m2 on day 1, repeated every 3 weeks) as adjuvant therapy",
        "interventionNames": [
          "Drug: docetaxel,0xaliplatin,capecitabine"
        ]
      },
      {
        "label": "B（Xelox）",
        "type": "ACTIVE_COMPARATOR",
        "description": "Interventions：This arm wil receive four cycles of Xelox (capecitabine 1,000 mg/m2 per day on days 1 to 14 and oxaliplatin 130mg/m2 on day 1, repeated every 3 weeks) as neoadjuvant therapy and four cycles of Xelox as adjuvant therapy",
        "interventionNames": [
          "Drug: oxaliplatin,capecitabine"
        ]
      },
      {
        "label": "C（Xelox）",
        "type": "ACTIVE_COMPARATOR",
        "description": "Interventions：This arm wil receive eight cycles of Xelox (capecitabine 1,000 mg/m2 per day on days 1 to 14 and oxaliplatin 130mg/m2 on day 1, repeated every 3 weeks) as adjuvant therapy.",
        "interventionNames": [
          "Drug: oxaliplatin,capecitabine"
        ]
      }
    ],
    "interventions": [
      {
        "type": "DRUG",
        "name": "docetaxel,0xaliplatin,capecitabine",
        "description": "docetaxel 60mg/m2， ivgtt，2h，d1;capecitabine 1000mg/m2 po bid d1-14; oxaliplatin 130mg/m2， ivgtt，2h，d1;q21d",
        "armGroupLabels": [
          "A（DOX）"
        ],
        "otherNames": [
          "AISU,AIHENG,AIBIN"
        ]
      },
      {
        "type": "DRUG",
        "name": "oxaliplatin,capecitabine",
        "description": "oxaliplatin 130mg/m2， ivgtt，2h，d1;capecitabine 1000mg/m2 po bid d1-14;q21d",
        "armGroupLabels": [
          "B（Xelox）",
          "C（Xelox）"
        ],
        "otherNames": [
          "AIHENG,AIBIN"
        ]
      }
    ]
  },
  "outcomesModule": {
    "primaryOutcomes": [
      {
        "measure": "The pathological complete response rate",
        "timeFrame": "24 weeks"
      }
    ],
    "secondaryOutcomes": [
      {
        "measure": "Overall survival(OS)",
        "timeFrame": "3 years"
      },
      {
        "measure": "Progression-free survival(PFS)",
        "timeFrame": "3 years"
      },
      {
        "measure": "Disease-free survival(DFS)",
        "timeFrame": "3 years"
      },
      {
        "measure": "Adverse events",
        "description": "Investigators graded all adverse events and toxic effects according to the National Cancer Institute's Common Toxicity Criteria, version 2.0. The number of Participants with adverse events will be recorded at each treatment visit.",
        "timeFrame": "3 years"
      }
    ]
  }
}

